files.spec.yaml:
yamaa: "1.0"
type: spec
model: SDTM
domain: DM
keys: [SUBJECT]
input:
  ODM: {path: source.xml, empty_string: present}
output:
  path: dm.parquet
  columns: [SUBJECT, TERM, EMPTY, NULLVAL, EVENTREPEAT, FORMREPEAT]
columns:
  - {name: SUBJECT, type: str, derivation: ODM.SubjectKey}
  - {name: TERM, type: str, derivation: {odm: ODM.I.DATE}}
  - {name: EMPTY, type: str, derivation: {odm: ODM.I.EMPTY}}
  - {name: NULLVAL, type: str, derivation: {odm: ODM.I.NULL}}
  - {name: EVENTREPEAT, type: str, derivation: ODM.StudyEventRepeatKey}
  - {name: FORMREPEAT, type: str, derivation: ODM.FormRepeatKey}
rows:
  - id: collected
    dataset: ODM
    group_by: [ODM.StudyOID, ODM.SubjectKey, ODM.StudyEventOID,
      ODM.StudyEventRepeatKey, ODM.FormOID, ODM.FormRepeatKey,
      ODM.ItemGroupOID, ODM.ItemGroupRepeatKey]
